type ExecutionKind = 'query' | 'explain' | 'transaction' | 'schema';
type ColumnTuple = readonly [name: string, type: TaskEvaluationColumn['type'], nullable?: boolean, tolerance?: number];
type TaskTuple = readonly [
  id: string,
  title: string,
  problem: string,
  solution: string,
  columns: readonly ColumnTuple[],
  family: string,
  grain: string,
  context: string,
  structureHint: string,
  adversarialCase: string,
  order?: string,
  execution?: ExecutionKind,
  duplicatePolicy?: 'preserve' | 'distinct'
];

const I = (name: string, nullable = false): ColumnTuple => [name, 'integer', nullable];
const R = (name: string, nullable = false, tolerance = 0.000001): ColumnTuple => [name, 'real', nullable, tolerance];
const T = (name: string, nullable = false): ColumnTuple => [name, 'text', nullable];

