function orderPolicy(source = ''): TaskOrderPolicy {
  if (!source) return { kind: 'unordered' };
  return {
    kind: 'ordered',
    keys: source.split(',').map(item => {
      const [column, direction] = item.split(':');
      return { column, direction: direction as 'asc' | 'desc', nulls: 'not-applicable' as const };
    }),
    completeTieBreak: true
  };
}

function statementPolicy(kind: ExecutionKind = 'query'): TaskStatementPolicy {
  if (kind === 'transaction') return { readOnly: false, singleStatement: false, sandbox: 'transaction-rollback' };
  if (kind === 'schema') return { readOnly: false, singleStatement: false, sandbox: 'schema-lab' };
  return { readOnly: true, singleStatement: true, ...(kind === 'explain' ? { allowExplain: true } : {}) };
}

type AuthoredRecord = { task: Partial<SqlTask> & Pick<SqlTask, 'id'>; evaluation: TaskEvaluationContract };

function authoredRecord(moduleId: string, tuple: TaskTuple, moduleTaskIds: readonly string[]): AuthoredRecord {
  const [id, title, problem, solution, columns, family, grain, context, structureHint, adversarialCase, order, execution, duplicatePolicy] = tuple;
  const transferFromTaskIds = moduleTaskIds.slice(1, 4);
  const learningContract: LearningTaskContract = {
    problemContract: problem,
    contextId: context,
    solutionFamily: family,
    expectedGrain: grain,
    stateRules: [
      order ? `Порядок обязателен: ${order}.` : 'Порядок строк не является частью смысла результата.',
      duplicatePolicy === 'distinct' ? 'Результат не содержит повторяющихся строк.' : 'Кратность строк сохраняется, если условие не требует агрегации.',
      execution === 'transaction' ? 'Изменение выполняется в транзакции и завершается ROLLBACK.' : execution === 'schema' ? 'DDL выполняется только в одноразовой лаборатории.' : 'Исходные таблицы не изменяются.'
    ],
    adversarialCases: [adversarialCase, 'Скрытый набор добавляет NULL, пустую связь или равные значения.'],
    remediationConcepts: [moduleId, family],
    transferFromTaskIds
  };
  return {
    task: {
      id,
      title,
      description: `${problem} Контракт результата: ${grain}.`,
      starter: `-- Сначала назови гранулярность результата и неизменяемое правило.\n`,
      solution,
      hints: [
        `Модель: ${grain}; сначала зафиксируй популяцию и смысл одной строки.`,
        `Структура: ${structureHint}`,
        `Проверка: ${adversarialCase}`
      ],
      evaluationContractId: `core:${id}`,
      learningContract
    },
    evaluation: {
      version: 'task-evaluation-v1',
      id: `core:${id}`,
      taskId: id,
      columns: columns.map(([name, type, nullable = false, numericTolerance]) => ({ name, type, nullable, ...(numericTolerance === undefined ? {} : { numericTolerance }) })),
      duplicatePolicy: duplicatePolicy || 'preserve',
      nullPolicy: 'preserve',
      order: orderPolicy(order),
      statementPolicy: statementPolicy(execution),
      postState: { tablesUnchanged: execution === 'schema' ? [] : allTables },
      fixtures: [...fixtures],
      requiredConcepts: ['result-grain', moduleId, family] as FoundationConcept[]
    }
  };
}

const records = Object.entries(authoredModules).flatMap(([moduleId, tuples]) => {
  const moduleTaskIds = tuples.map(tuple => tuple[0]);
  return tuples.map(tuple => authoredRecord(moduleId, tuple, moduleTaskIds));
});
