export const coreAuthoredEvaluationContracts = [...records, ...checkpointRecords].map(record => record.evaluation);
export const coreAuthoredTaskIds = records.map(record => record.task.id);
export const coreCheckpointAuthoredTaskBlueprints = checkpointRecords.map(record => ({
  module: record.evaluation.id.replace(/^core:checkpoint-core-/, ''),
  ...record.task
}));

export function applyCoreAuthoredTasks(source: readonly SqlTask[]): SqlTask[] {
  return source.map(task => {
    const override = authoredById.get(task.id);
    if (override) return { ...task, ...override };
    const number = /^task-(\d+)$/.exec(task.id)?.[1];
    if (!number || Number(number) > 18) return task;
    const moduleTaskIds = source.filter(candidate => candidate.module === task.module).map(candidate => candidate.id);
    return {
      ...task,
      ...(foundationTransferSolutions.has(task.id) ? { solution: foundationTransferSolutions.get(task.id)! } : {}),
      learningContract: {
        problemContract: task.description,
        contextId: `foundation-${task.module}-${task.id}`,
        solutionFamily: `foundation-${task.module}-${task.id}`,
        expectedGrain: 'Гранулярность явно задана условием и проверяется по всем строкам результата.',
        stateRules: ['Исходные таблицы не изменяются.', 'NULL и кратность строк сохраняют смысл условия.'],
        adversarialCases: ['Скрытый набор содержит NULL.', 'Скрытый набор содержит дубли или равные значения.'],
        remediationConcepts: [task.module, task.topic],
        transferFromTaskIds: moduleTaskIds.slice(1, 4)
      }
    };
  });
}
